package bookstore

import "sort"

// groupCost[i] is the price (in cents) of a group of i distinct books.
// One book costs $8 (800c); groups of distinct titles get a discount:
//   1 -> 0%, 2 -> 5%, 3 -> 10%, 4 -> 20%, 5 -> 25%.
var groupCost = [6]int{0, 800, 1520, 2160, 2560, 3000}

// Cost returns the minimum total price, in cents, for the given basket of
// books. Each book is identified by an integer 1..5 (the five titles of the
// series). The basket is partitioned into groups of distinct titles so that
// the total discount is as large as possible.
func Cost(books []int) int {
	var c [5]int
	for _, b := range books {
		if b >= 1 && b <= 5 {
			c[b-1]++
		}
	}
	return minCost(c)
}

// minCost computes the optimal price for a basket described by the per-title
// copy counts, using memoized search over the count vector. The five titles
// are interchangeable (same base price, discounts depend only on how many
// distinct titles a group contains), so states are canonicalized by sorting
// the counts before memoizing.
func minCost(c [5]int) int {
	memo := make(map[[5]int]int)
	return solve(c, memo)
}

func solve(c [5]int, memo map[[5]int]int) int {
	// Canonicalize: sort counts so permuted states share a memo entry.
	sort.Ints(c[:])

	if v, ok := memo[c]; ok {
		return v
	}

	// Base case: nothing left to buy.
	empty := true
	for _, n := range c {
		if n != 0 {
			empty = false
			break
		}
	}
	if empty {
		memo[c] = 0
		return 0
	}

	best := -1
	// Try every non-empty subset of titles as the next group.
	for mask := 1; mask < 32; mask++ {
		size := 0
		valid := true
		for i := 0; i < 5; i++ {
			if mask&(1<<i) != 0 {
				if c[i] == 0 {
					valid = false
					break
				}
				size++
			}
		}
		if !valid {
			continue
		}
		next := c
		for i := 0; i < 5; i++ {
			if mask&(1<<i) != 0 {
				next[i]--
			}
		}
		cost := groupCost[size] + solve(next, memo)
		if best < 0 || cost < best {
			best = cost
		}
	}

	memo[c] = best
	return best
}
